      "common_side_effects": [
        "severe skin reactions",
        "liver damage if too much is taken"
      ],
      "key_warning": "taking more than 4,000 mg in 24 hours or with alcohol can cause serious liver damage"
    },
    {
      "generic": "enoxaparin",
      "plain_purpose": "a blood thinner used to prevent or treat blood clots",
      "common_side_effects": [
        "bleeding",
        "low platelet count",
        "injection site pain",
        "nausea"
      ],
      "key_warning": "can cause spinal or epidural bleeding leading to paralysis if you have a spinal puncture or epidural anesthesia"
    },
    {
      "generic": "docusate",
      "plain_purpose": "a stool softener that helps relieve occasional constipation",
      "common_side_effects": [],
      "key_warning": "stop using and see a doctor if you have rectal bleeding or no bowel movement after use"
    },
    {
      "generic": "ondansetron",
      "plain_purpose": "a medicine that prevents nausea and vomiting from chemotherapy, radiation, or surgery",
      "common_side_effects": [
        "headache",
        "tiredness",
        "constipation",
        "diarrhea"
      ],
      "key_warning": "can cause a dangerous heart rhythm problem (QT prolongation) especially with certain other drugs or conditions"
    }
  ]
